style:
/* Source of truth for the Argent disponible workspace widget (synced on migrate). */
.fonds-live {
  --fg: var(--text-color, #1f272e);
  --muted: var(--text-muted, #6c7680);
  --card: var(--card-bg, #fff);
  --line: var(--border-color, #e3e8ee);
  --accent: #0f6b4c;
  --neg: #b42318;
  font-family: inherit;
  color: var(--fg);
}
.fonds-live__header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}
.fonds-live__title { font-size: 1.05rem; font-weight: 700; }
.fonds-live__meta { margin-top: 4px; font-size: 0.82rem; color: var(--muted); }
.fonds-live__btn {
  border: 1px solid var(--line);
  background: var(--card);
  color: var(--fg);
  border-radius: 8px;
  padding: 7px 12px;
  cursor: pointer;
  font-weight: 600;
}
.fonds-live__btn:hover { border-color: var(--accent); }
.fonds-live__btn:disabled { opacity: 0.6; cursor: wait; }
.fonds-live__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 10px;
}
.fonds-live__card {
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 12px 14px;
}
.fonds-live__name {
  font-size: 0.78rem;
  font-weight: 600;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.fonds-live__hero {
  margin-top: 4px;
  font-size: 1.4rem;
  font-weight: 750;
  color: var(--accent);
  line-height: 1.2;
}
.fonds-live__hero.is-neg { color: var(--neg); }
.fonds-live__ar {
  margin-top: 4px;
  font-size: 0.78rem;
  color: var(--muted);
  line-height: 1.3;
}
.fonds-live__total {
  color: var(--accent);
  font-weight: 700;
}
.fonds-live__total.is-neg { color: var(--neg); }
.fonds-live__details {
  margin-top: 8px;
  font-size: 0.72rem;
  color: var(--muted);
  line-height: 1.4;
}
.fonds-live__loading {
  padding: 18px;
  color: var(--muted);
  border: 1px dashed var(--line);
  border-radius: 10px;
}
.fonds-live__error {
  margin-top: 10px;
  padding: 10px 12px;
  border-radius: 8px;
  background: #fef3f2;
  color: var(--neg);
  font-size: 0.85rem;
}
